# The pattern seems to be:
# - Find gap columns (columns where some non-empty row has 0)
# - For each gap column, find the "floor" row (highest non-empty row where gap column has 0)
# - 2s extend from this floor downward until reaching the next non-empty row

# Let me implement the full transform function based on this analysis

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    if w == 0:
        return grid

    # Find non-empty rows (rows with at least one 8)
    empty_rows = [r for r in range(h) if not any(grid[r][c] == 8 for c in range(w))]
    non_empty_rows = [r for r in range(h) if r not in empty_rows]

    # Find gap columns (columns where some non-empty row has 0)
    gap_cols = set()
    for r in non_empty_rows:
        for c in range(w):
            if grid[r][c] == 0:
                gap_cols.add(c)

    # For each gap column, find the "floor" row (highest non-empty row where this column has 0)
    floor_cols = {}  # gap column -> floor row
    for c in gap_cols:
        floor_row = None
        for r in reversed(non_empty_rows):  # from highest non-empty row
            if grid[r][c] == 0:
                floor_row = r
                break
        floor_cols[c] = floor_row

    # Build the output
    # First, copy all 8s from input to output (preserving their positions)
    output = [row[:] for row in grid]

    # For rows that have 8s, replace 0s in gap_cols with 2s (below the floor)
    for r in non_empty_rows:
        for c in gap_cols:
            if grid[r][c] == 0 and r > floor_cols[c]:
                output[r][c] = 2

    # For empty rows, they become rows of 2s if they're "below" a boundary
    # Based on analysis: boundary row = last non-empty row floor for gap cols
    if non_empty_rows:
        last_floor = max(floor_cols.values())  # highest floor
        # Empty rows at or below last_floor become 2s
        for r in empty_rows:
            if r >= last_floor:
                for c in range(w):
                    output[r][c] = 2

    return output

